def materialize(context):
    for kind in ['class', 'data', 'object']:
        for rule in all_rules(context, kind):
            for row in rows(context, rule):
                if kind == 'class':
                    emit_type(context, rule, row)
                elif kind == 'data':
                    emit_data(context, rule, row)
                else:
                    emit_object(context, rule, row)

def materialize(context):
    for rule in all_rules(context, 'object'):
        for row in rows(context, rule):
            emit_object(context, rule, row)
